type CarbonWorkspaceSection = 'operational' | 'overview' | 'analytics' | 'recommendations';

const resolveCarbonWorkspaceSection = (search: string): CarbonWorkspaceSection => {
  const section = new URLSearchParams(search).get('section');
  if (section === 'operational') {
    return 'operational';
  }
  if (section === 'recommendations') {
    return 'recommendations';
  }
  if (section === 'overview' || section === 'assessment-results' || section === 'start-assessment') {
    return 'overview';
  }
  if (section === 'carbon-analytics' || section === 'analytics') {
    return 'analytics';
  }
  return 'analytics';
};

